async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
    throw new Error(`Unknown tool: ${name}`);
  }

  let validate = tool.validateInput;
  if (typeof tool.definitionSource === 'function') {
    const currentDefinition = this.resolveDefinition(tool.definitionSource);
    if (currentDefinition.inputSchema !== tool.cachedSchema) {
      validate = compileSchema(currentDefinition.name, currentDefinition.inputSchema);
      tool.cachedSchema = currentDefinition.inputSchema;
      tool.validateInput = validate;
    }
  }

  if (!validate(input)) {
    const errors = validate.errors ?? [];
    const messages = errors.map(err => {
      if (err.keyword === 'required') {
        return `Field "${err.instancePath ? err.instancePath + '.' : ''}${err.params.missingProperty}" is required`;
      }
      const expectedType = err.keyword === 'type' ? err.params.type : '';
      return `Field "${err.instancePath || 'input'}" ${err.message}${expectedType ? ` (expected ${expectedType})` : ''}`;
    });
    return {result: `Invalid input: ${messages.join(', ')}`};
  }

  log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
  const rawResult = await tool.execute(input, context);
  const response = normalizeToolResponse(rawResult);
  log.info('tool', 'execution complete', {
    name,
    rawType: typeof rawResult,
    clientMessageCount: response.clientMessages?.length ?? 0,
    clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
    suppressAssistantResponse: response.suppressAssistantResponse ?? false,
  });
  return response;
}

